# Input palette.
_BG, _BLUE, _RED, _YELLOW, _TEAL = 0, 1, 2, 4, 8
_REQUIRED_INPUT_COLORS = {_BG, _BLUE, _RED, _TEAL}

# Canvas and source rectangle bounds.
_GRID_HEIGHT = 19
_GRID_WIDTH_RANGE = (18, 19)
_SOURCE_SIZE_RANGE = (4, 7)
_SOURCE_EDGE_GAP, _SOURCE_MAX_TOP, _SOURCE_CENTER_JITTER = 4, 7, 2

# Object separation and blocker rectangle bounds.
_MIN_OBJECT_GAP, _RAY_OBJECT_GAP = 1, 1
_BLOCKER_COUNT_RANGE = (1, 4)
_BLOCKER_HEIGHTS = range(2, 9)
_BLOCKER_WIDTHS = range(2, 10)

# Passthrough red rectangle bounds.
_RED_COUNT_RANGE = (2, 6)
_RED_PATH_COUNT_MIN = 1
_RED_HEIGHTS = range(2, 7)
_RED_WIDTHS = range(2, 14)

# Retry budget for valid oracle-checked samples.
_MAX_GENERATION_ATTEMPTS = 300


def _fits(rect, rects, H, W):
    r0, c0, r1, c1 = rect
    if r0 < 0 or c0 < 0 or r1 >= H or c1 >= W:
        return False
    for or0, oc0, or1, oc1 in rects:
        if not (
            r1 < or0 - _MIN_OBJECT_GAP
            or r0 > or1 + _MIN_OBJECT_GAP
            or c1 < oc0 - _MIN_OBJECT_GAP
            or c0 > oc1 + _MIN_OBJECT_GAP
        ):
            return False
    return True


def _place(grid, rect, color):
    r0, c0, r1, c1 = rect
    patch = np.full((r1 - r0 + 1, c1 - c0 + 1), color, dtype=int)
    paste(grid, patch, r0, c0)


def _source_rect(H, W):
    h = random.randint(*_SOURCE_SIZE_RANGE)
    w = random.randint(*_SOURCE_SIZE_RANGE)
    r_hi = min(_SOURCE_MAX_TOP, H - h - _SOURCE_EDGE_GAP)
    r0 = random.randint(_SOURCE_EDGE_GAP, r_hi)

    c_lo, c_hi = _SOURCE_EDGE_GAP, W - w - _SOURCE_EDGE_GAP
    center = (W - w) // 2
    c_lo = max(c_lo, center - _SOURCE_CENTER_JITTER)
    c_hi = min(c_hi, center + _SOURCE_CENTER_JITTER)
    c0 = random.randint(c_lo, c_hi)
    return (r0, c0, r0 + h - 1, c0 + w - 1)


def _choose_grouped(candidates):
    if not candidates:
        return None
    groups = {}
    for item in candidates:
        groups.setdefault(item[1], []).append(item[0])
    return random.choice(random.choice(list(groups.values())))


def _is_visible_blocker(grid, source, rect, axis, side):
    sr0, sc0, sr1, sc1 = source
    r0, c0, r1, c1 = rect
    if axis == "h":
        for r in range(max(sr0, r0), min(sr1, r1) + 1):
            if side == "left":
                if not np.any(grid[r, c1 + 1 : sc0] == _BLUE):
                    return True
            else:
                if not np.any(grid[r, sc1 + 1 : c0] == _BLUE):
                    return True
    else:
        for c in range(max(sc0, c0), min(sc1, c1) + 1):
            if side == "up":
                if not np.any(grid[r1 + 1 : sr0, c] == _BLUE):
                    return True
            else:
                if not np.any(grid[sr1 + 1 : r0, c] == _BLUE):
                    return True
    return False


def _blocker_candidates(grid, source, rects):
    H, W = grid.shape
    sr0, sc0, sr1, sc1 = source
    candidates = []

    for h in _BLOCKER_HEIGHTS:
        for w in _BLOCKER_WIDTHS:
            for r in range(max(0, sr0 - h + 1), min(sr1, H - h) + 1):
                for side, c_range in (
                    ("left", range(0, sc0 - w - _RAY_OBJECT_GAP + 1)),
                    ("right", range(sc1 + _RAY_OBJECT_GAP + 1, W - w + 1)),
                ):
                    for c in c_range:
                        rect = (r, c, r + h - 1, c + w - 1)
                        if _fits(rect, rects, H, W) and _is_visible_blocker(grid, source, rect, "h", side):
                            candidates.append((rect, ("h", side, h, w)))

            for c in range(max(0, sc0 - w + 1), min(sc1, W - w) + 1):
                for side, r_range in (
                    ("up", range(0, sr0 - h - _RAY_OBJECT_GAP + 1)),
                    ("down", range(sr1 + _RAY_OBJECT_GAP + 1, H - h + 1)),
                ):
                    for r in r_range:
                        rect = (r, c, r + h - 1, c + w - 1)
                        if _fits(rect, rects, H, W) and _is_visible_blocker(grid, source, rect, "v", side):
                            candidates.append((rect, ("v", side, h, w)))

    return candidates


def _place_blockers(grid, source, rects):
    """Place visible blue blockers; return False if any required choice fails."""
    for _ in range(random.randint(*_BLOCKER_COUNT_RANGE)):
        rect = _choose_grouped(_blocker_candidates(grid, source, rects))
        if rect is None:
            return False
        _place(grid, rect, _BLUE)
        rects.append(rect)
    return True


def _ray_mask(grid, source):
    H, W = grid.shape
    sr0, sc0, sr1, sc1 = source
    mask = np.zeros((H, W), dtype=bool)
    for r in range(sr0, sr1 + 1):
        for c in range(sc0 - 1, -1, -1):
            if grid[r, c] == _BLUE:
                break
            mask[r, c] = True
        for c in range(sc1 + 1, W):
            if grid[r, c] == _BLUE:
                break
            mask[r, c] = True
    for c in range(sc0, sc1 + 1):
        for r in range(sr0 - 1, -1, -1):
            if grid[r, c] == _BLUE:
                break
            mask[r, c] = True
        for r in range(sr1 + 1, H):
            if grid[r, c] == _BLUE:
                break
            mask[r, c] = True

from __future__ import annotations
import numpy as np
from arc_utils import colors_present, get_bg
import random
from arc_utils import is_contiguous

def main(grid: np.ndarray) -> np.ndarray:
    """
    Cut a sprite along border-control rays and slide pieces to grid corners.

    Input structure:
    - bg, fg (main object, ~centered), ctrl (1-2 pixels on grid edges).

    Rule:
    - Draw rays inward from each ctrl pixel along its row/col, painting only bg cells up to the farthest fg pixel (intermittent).
    - Rays partition the grid; fg on the cut line stays in place.
    - Cut pieces in regions touching a control edge slide to that corner; others vanish.

    Key insight: Only regions sharing a border edge with a control pixel keep their piece; the ray skips fg cells.
    """
    g = np.array(grid, dtype=int)
    H, W = g.shape
    bg = int(get_bg(g))

    nonbg = colors_present(g, exclude={bg})

    # Control color is the only non-bg color present on the border.
    border_cols = set(map(int, g[0, :])) | set(map(int, g[-1, :])) | set(map(int, g[:, 0])) | set(map(int, g[:, -1]))
    border_cols.discard(int(bg))
    assert not (not border_cols)
    ctrl = int(sorted(border_cols)[0])
    fg = int(next(c for c in nonbg if int(c) != int(ctrl)))

    ctrl_pts = [(int(r), int(c)) for r, c in np.argwhere(g == int(ctrl))]

    # Split lines (at most one vertical and one horizontal in these tasks).
    E: set[str] = set()
    c_split: int | None = None
    r_split: int | None = None
    for r, c in ctrl_pts:
        if int(r) == 0:
            E.add("top")
            c_split = int(c)
        elif int(r) == int(H - 1):
            E.add("bottom")
            c_split = int(c)
        elif int(c) == 0:
            E.add("left")
            r_split = int(r)
        elif int(c) == int(W - 1):
            E.add("right")
            r_split = int(r)

    out = np.full((H, W), int(bg), dtype=int)

    # --- Stage 1: draw rays on background cells only (but keep the control pixel itself). ---
    for r, c in ctrl_pts:
        if int(r) == 0:
            rows = [int(rr) for rr in np.argwhere(g[:, int(c)] == int(fg)).flatten()]
            if rows:
                stop = int(max(rows))
                for rr in range(0, int(stop) + 1):
                    if int(g[int(rr), int(c)]) == int(bg):
                        out[int(rr), int(c)] = int(ctrl)
        elif int(r) == int(H - 1):
            rows = [int(rr) for rr in np.argwhere(g[:, int(c)] == int(fg)).flatten()]
            if rows:
                stop = int(min(rows))
                for rr in range(int(H - 1), int(stop) - 1, -1):
                    if int(g[int(rr), int(c)]) == int(bg):
                        out[int(rr), int(c)] = int(ctrl)
        elif int(c) == 0:
            cols = [int(cc) for cc in np.argwhere(g[int(r), :] == int(fg)).flatten()]
            if cols:
                stop = int(max(cols))
                for cc in range(0, int(stop) + 1):
                    if int(g[int(r), int(cc)]) == int(bg):
                        out[int(r), int(cc)] = int(ctrl)
        elif int(c) == int(W - 1):
            cols = [int(cc) for cc in np.argwhere(g[int(r), :] == int(fg)).flatten()]
            if cols:
                stop = int(min(cols))
                for cc in range(int(W - 1), int(stop) - 1, -1):
                    if int(g[int(r), int(cc)]) == int(bg):
                        out[int(r), int(cc)] = int(ctrl)

    for r, c in ctrl_pts:
        out[int(r), int(c)] = int(ctrl)

    # Foreground pixels on split line(s) remain in place.
    for r, c in np.argwhere(g == int(fg)):
        r = int(r)
        c = int(c)
        if (c_split is not None and int(c) == int(c_split)) or (r_split is not None and int(r) == int(r_split)):
            out[int(r), int(c)] = int(fg)

    # --- Stage 2: move cut parts from each rectangular region to its target corner. ---
    regions: dict[tuple[str, str], list[tuple[int, int]]] = {}
    for r, c in np.argwhere(g == int(fg)):
        r = int(r)
        c = int(c)
        if (c_split is not None and int(c) == int(c_split)) or (r_split is not None and int(r) == int(r_split)):
            continue
        hs = "A"
        vs = "A"
        if r_split is not None:
            hs = "T" if int(r) < int(r_split) else "B"
        if c_split is not None:
            vs = "L" if int(c) < int(c_split) else "R"
        regions.setdefault((hs, vs), []).append((int(r), int(c)))

    def touches_edges(hs: str, vs: str) -> set[str]:
        te: set[str] = set()
        if hs in ("T", "A"):
            te.add("top")
        if hs in ("B", "A"):
            te.add("bottom")
        if vs in ("L", "A"):
            te.add("left")
        if vs in ("R", "A"):
            te.add("right")
        return te

    def pick_dest(hs: str, vs: str) -> tuple[str, str]:
        if r_split is not None:
            dh = hs
        else:
            if ("top" in E) and ("bottom" not in E):
                dh = "T"
            elif ("bottom" in E) and ("top" not in E):
                dh = "B"
            else:
                dh = "T"
        if c_split is not None:
            dv = vs
        else:
            if ("left" in E) and ("right" not in E):
                dv = "L"
            elif ("right" in E) and ("left" not in E):
                dv = "R"
            else:
                dv = "L"
        return str(dh), str(dv)

    for (hs, vs), pts in regions.items():
        if not (touches_edges(hs, vs) & E):
            continue

        dh, dv = pick_dest(hs, vs)
        rs = [r for r, _ in pts]
        cs = [c for _, c in pts]
        rmin, rmax = int(min(rs)), int(max(rs))
        cmin, cmax = int(min(cs)), int(max(cs))
        dr = int(0 - rmin) if dh == "T" else int((H - 1) - rmax)
        dc = int(0 - cmin) if dv == "L" else int((W - 1) - cmax)

        for r, c in pts:
            rr = int(r + dr)
            cc = int(c + dc)
            if 0 <= rr < H and 0 <= cc < W:
                out[int(rr), int(cc)] = int(fg)

    return out

# --------------- generator (Claude#1) ---------------

def _grow_piece(max_h, max_w, target_px):
    """Grow a connected piece up to max_h x max_w targeting target_px pixels."""
    cells = {(0, 0)}
    for _ in range(target_px - 1):
        neighbors = set()
        for r, c in cells:
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = r+dr, c+dc
                if (nr, nc) not in cells:
                    neighbors.add((nr, nc))
        valid = [(nr, nc) for nr, nc in neighbors
                 if max(r for r, _ in cells | {(nr,nc)}) - min(r for r, _ in cells | {(nr,nc)}) + 1 <= max_h
                 and max(c for _, c in cells | {(nr,nc)}) - min(c for _, c in cells | {(nr,nc)}) + 1 <= max_w]
        if not valid: break
        cells.add(random.choice(valid))
    rs = [r for r, _ in cells]; cs = [c for _, c in cells]
    return frozenset((r - min(rs), c - min(cs)) for r, c in cells)


def _gen_attempt():
    S = random.randint(18, 20)
    H = W = S
    bg, fg, ctrl_color = 1, 7, 2

    # Weight toward 2-ctrl to compensate for higher rejection rate
    num_ctrl = random.choices([1, 2], weights=[1, 4])[0]
    if num_ctrl == 1:
        ctrl_edges = [random.choice(['top', 'bottom', 'left', 'right'])]
    else:
        ctrl_edges = [random.choice(['top', 'bottom']), random.choice(['left', 'right'])]

    c_split = r_split = None
    ctrl_pts = []
    E = set(ctrl_edges)
    has_v = has_h = False

    for edge in ctrl_edges:
        if edge in ('top', 'bottom'):
            c_split = random.randint(int(W*0.4), int(W*0.6))
            ctrl_pts.append((0 if edge == 'top' else H-1, c_split))
            has_v = True
        else:
            r_split = random.randint(int(H*0.4), int(H*0.6))
            ctrl_pts.append((r_split, 0 if edge == 'left' else W-1))
            has_h = True

    def pick_dest(hs, vs):
        if r_split is not None: dh = hs
        elif 'top' in E and 'bottom' not in E: dh = 'T'
        elif 'bottom' in E and 'top' not in E: dh = 'B'
        else: dh = 'T'
        if c_split is not None: dv = vs
        elif 'left' in E and 'right' not in E: dv = 'L'
        elif 'right' in E and 'left' not in E: dv = 'R'
        else: dv = 'L'
        return dh, dv

    def touches_E(hs, vs):
        te = set()
        if hs in ('T','A'): te.add('top')
        if hs in ('B','A'): te.add('bottom')
        if vs in ('L','A'): te.add('left')
        if vs in ('R','A'): te.add('right')
        return bool(te & E)

    if has_h and has_v:
        all_regions = [('T','L'), ('T','R'), ('B','L'), ('B','R')]
    elif has_v:
        all_regions = [('A','L'), ('A','R')]
    else:
        all_regions = [('T','A'), ('B','A')]

    kept = [r for r in all_regions if touches_E(*r)]
    vanish = [r for r in all_regions if r not in kept]

    # Sprite bbox (spec: 5-8 x 8-10)
    sprite_h = random.randint(5, 8)
    sprite_w = random.randint(8, 10)

    # Place sprite with split at 40-60% through bbox
    if has_v:
        frac = random.uniform(0.4, 0.6)
        sprite_c0 = c_split - int(frac * sprite_w)
        sprite_c0 = max(4, min(sprite_c0, W - 5 - sprite_w + 1))
        if sprite_c0 > W - 5 - sprite_w + 1: return None
        if c_split <= sprite_c0 or c_split >= sprite_c0 + sprite_w - 1: return None
    else:
        hi = W - 5 - sprite_w + 1
        if hi < 4: return None
        sprite_c0 = random.randint(4, hi)

    if has_h:
        frac = random.uniform(0.4, 0.6)
        sprite_r0 = r_split - int(frac * sprite_h)
        sprite_r0 = max(4, min(sprite_r0, H - 5 - sprite_h + 1))
        if sprite_r0 > H - 5 - sprite_h + 1: return None
        if r_split <= sprite_r0 or r_split >= sprite_r0 + sprite_h - 1: return None
    else:
        hi = H - 5 - sprite_h + 1
        if hi < 4: return None
        sprite_r0 = random.randint(4, hi)

    sprite_r1 = sprite_r0 + sprite_h - 1
    sprite_c1 = sprite_c0 + sprite_w - 1

    def sub_bbox(hs, vs):
        r0 = sprite_r0 if hs in ('T','A') else r_split + 1
        r1 = (r_split - 1 if hs == 'T' else sprite_r1) if has_h else sprite_r1
        c0 = sprite_c0 if vs in ('L','A') else c_split + 1
        c1 = (c_split - 1 if vs == 'L' else sprite_c1) if has_v else sprite_c1
        return r0, r1, c0, c1

    for reg in kept + vanish:
        r0, r1, c0, c1 = sub_bbox(*reg)

from __future__ import annotations

import numpy as np

from arc_utils import Color, bbox_coords, components_mask
import random

BBox = tuple[int, int, int, int]


def _edge_side(bbox: BBox, shape: tuple[int, int]) -> str:
    r0, c0, r1, c1 = bbox
    h, w = shape
    sides = []
    if r0 == 0:
        sides.append("top")
    if r1 == h - 1:
        sides.append("bottom")
    if c0 == 0:
        sides.append("left")
    if c1 == w - 1:
        sides.append("right")
    assert len(sides) == 1, "each black rectangle must touch exactly one grid edge"
    return sides[0]


def main(grid: np.ndarray) -> np.ndarray:
    """
    Slide each black border rectangle to the opposite border, recoloring its swept stripe orange and leaving the rectangle black at the far edge.

    Input structure
    - The grid contains black rectangular 4-connected masks, each touching exactly one outer border.
    - Grey cells form incidental pattern content; orange is the trail color used when a black mask slides.

    Rule
    - Treat all black rectangles as moving simultaneously.
    - A rectangle touching the top or bottom edge moves vertically to the opposite edge in the same columns.
    - A rectangle touching the left or right edge moves horizontally to the opposite edge in the same rows.
    - Recolor the complete swept row or column stripe to orange, then stamp every destination rectangle in black.

    Key insight
    - Edge contact gives the slide direction; the output is the set of opposite-edge black rectangles plus their orange trails.
    """
    g = np.asarray(grid, dtype=int)
    assert g.ndim == 2
    h, w = g.shape
    assert h > 0 and w > 0

    moving = Color.BLACK
    trail = Color.ORANGE
    assert np.any(g == moving), "expected at least one black rectangle"
    assert np.any(g == trail), "expected orange trail color to be present"

    out = g.copy()
    targets: list[BBox] = []
    for coords in components_mask(g == moving, connectivity=4):
        r0, c0, r1, c1 = bbox_coords(coords)
        rect_h = r1 - r0 + 1
        rect_w = c1 - c0 + 1
        assert int(coords.shape[0]) == rect_h * rect_w, "black mask must be a solid rectangle"

        side = _edge_side((r0, c0, r1, c1), g.shape)
        if side == "top":
            out[:, c0 : c1 + 1] = trail
            targets.append((h - rect_h, c0, h - 1, c1))
        elif side == "bottom":
            out[:, c0 : c1 + 1] = trail
            targets.append((0, c0, rect_h - 1, c1))
        elif side == "left":
            out[r0 : r1 + 1, :] = trail
            targets.append((r0, w - rect_w, r1, w - 1))
        else:
            assert side == "right"
            out[r0 : r1 + 1, :] = trail
            targets.append((r0, 0, r1, rect_w - 1))

    for r0, c0, r1, c1 in targets:
        out[r0 : r1 + 1, c0 : c1 + 1] = moving

    return out

